using System;using System.Linq;
namespace LoopPedal {
sealed class PerformanceControl:PerformanceTimeline.Port {
 public readonly Engine[] Banks;public volatile bool NeedsPrepare;public PerformanceControl(Engine[] banks){Banks=banks;}
 public Layer Layer(int target,long id){int bank=(target-1000)/8;if(bank<0||bank>1)return null;for(int i=0;i<Banks[bank].Layers.Count;i++){var l=Banks[bank].Layers[i];if(l.AudioId==id||id==0&&Banks[bank].Destructive)return l;}return null;}
 public float get(int target,long audio){if(target==300)return (float)Banks[0].Master;if(target<1000)return FxParameters.Get(Banks[target>=200?1:0].Fx,target%100);var l=Layer(target,audio);if(l==null)return 0;int k=(target-1000)%8;return (float)(k==0?(SamplerPlayback.Time(l)-.5)/1.5:k==1?(SamplerPlayback.Pitch(l)+12)/24:k==2?Math.Log(l.Cutoff/40)/Math.Log(500):k==3?l.Gain/1.5:(l.Pan+1)/2);}
 public void set(int target,long audio,float v){if(target==300){foreach(var bank in Banks)bank.Master=Math.Max(0,Math.Min(1,v));return;}v=Math.Max(0,Math.Min(1,v));if(target<1000){FxParameters.Set(Banks[target>=200?1:0].Fx,target%100,v);return;}var l=Layer(target,audio);if(l==null)return;int k=(target-1000)%8;var b=Banks[(target-1000)/8];if(k==0)SamplerPlayback.SetStretch(l,.5+v*1.5);if(k==1)SamplerPlayback.SetPitch(l,v*24-12);if(k==2)l.Cutoff=40*Math.Pow(500,v);if(k==3)l.Gain=v*1.5;if(k==4)l.Pan=v*2-1;if(k<2&&l.PlaybackMode>0&&!b.WarpLayers){SamplerPlayback.Update(b,l);return;}if(k<2&&l.Stream==null)NeedsPrepare=true;if(k<2&&l.Stream!=null){double stretch=b.EffectiveStretch(l);l.Stream.Configure(l.LiveSource,stretch,l.Pitch,l.Reverse,l.PreserveFormants,b.Frame,b.WarpLayers?b.LoopOrigin:l.Offset);l.LivePlaybackFrames=Math.Max(1,(int)(l.LiveSource.Length/2*stretch));if(!b.WarpLayers&&b.Layers.Count>0&&object.ReferenceEquals(b.Layers[0],l))b.LoopFrames=l.LivePlaybackFrames;}}
 public void Prepare(int target,long audio){if(target<1000||(target-1000)%8>1)return;var l=Layer(target,audio);if(l==null)return;var b=Banks[(target-1000)/8];l.LiveMode=true;if(l.PlaybackMode>0&&!b.WarpLayers){var input=DSP.Region(l.Original,l.TrimStart,l.TrimLength);l.LiveSource=input;l.LiveFallback=l.Reverse?DSP.Render(input,1,0,true):input;l.LiveTrimStart=l.TrimStart;l.LiveTrimLength=l.TrimLength;l.LiveReverse=l.Reverse;l.Audio=l.LiveFallback;SamplerPlayback.Update(b,l);return;}if(l.Stream!=null)return;var source=DSP.Region(l.Original,l.TrimStart,l.TrimLength);var stream=new LiveStretch(source,b.EffectiveStretch(l),l.Pitch,l.Reverse,l.PreserveFormants,b.Frame,b.WarpLayers?b.LoopOrigin:l.Offset);lock(b.Gate){l.LiveSource=source;l.LiveTrimStart=l.TrimStart;l.LiveTrimLength=l.TrimLength;l.LiveReverse=l.Reverse;l.LiveFallback=l.Reverse?DSP.Render(source,1,0,true):source;l.PreviousAudio=l.Audio;l.Audio=l.LiveFallback;l.Transition=960;l.LivePlaybackFrames=Math.Max(1,(int)(source.Length/2*b.EffectiveStretch(l)));l.Stream=stream;}}
 public long cycle(int bank){return Banks[bank].LoopFrames>0?Banks[bank].LoopFrames:(long)(48000*60/Banks[0].BPM*Banks[0].BeatsPerBar*4/Banks[0].BeatUnit);}
 public long phase(int bank){return Banks[bank].Frame-Banks[bank].LoopOrigin;}public double tempo(){return Banks[0].BPM;}public bool running(){return Banks[0].Playing||Banks[1].Playing||Banks[0].Recording||Banks[1].Recording||Banks[0].Fx.Freeze&&Banks[0].Fx.Grain>0||!Banks[0].SingleLooper&&Banks[1].Fx.Freeze&&Banks[1].Fx.Grain>0;}public float envelope(){return Banks[0].Peak;}
}
partial class Engine {public PerformanceTimeline Performance;public PerformanceControl Controls;}
}
